const $=id=>document.getElementById(id),safe=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\\':'&#92;','"':'&quot;'}[c]));
const rows=window.IPCP_NCRP_DATA.sheets['Site-wise Incidence 2022'];
const map={'Breast cancer':'Breast','Lung cancer':'Lung and bronchus','Cervical cancer':'Uterine cervix','Oral cavity cancer':'Oral cavity and pharynx'};
const care={'Breast cancer':['PBCR-West','District referral · MH-04','NCG-07 · tertiary'],'Lung cancer':['PBCR-North','District referral · AS-02','NCG-12 · tertiary'],'Cervical cancer':['PBCR-South','District referral · KA-11','NCG-03 · tertiary'],'Oral cavity cancer':['PBCR-East','District referral · OD-08','NCG-22 · tertiary']};
function dataRow(){return rows.slice(4).find(r=>r[0]===map[$('cohort').value])||rows[4]}
function metrics(){const r=dataRow();$('totalCases').textContent=Number(r[9]||0).toLocaleString('en-IN');$('maleCases').textContent=r[1]==null?'—':Number(r[1]).toLocaleString('en-IN');$('femaleCases').textContent=r[5]==null?'—':Number(r[5]).toLocaleString('en-IN');$('bothAar').textContent=r[11]??'—'}
function pathway(){const c=$('cohort').value;$('records').innerHTML=care[c].map((x,i)=>`<div class="record"><div><b>${x}</b><br><small>${i===0?'Population registry estimate':i===1?'Referral-origin record':'Tertiary oncology record'}</small></div><div><span class="tag ${i===1?'warn':'ok'}">${i===1?'LIMITED':'SOURCE'}</span></div></div>`).join('')}
function sexChart(r){const m=Number(r[1]||0),f=Number(r[5]||0),max=Math.max(m,f,1);return `<div class="muted" style="margin:12px 0 4px">${safe(map[$('cohort').value])} · 2022 estimated cases by sex</div><svg viewBox="0 0 520 90" role="img" aria-label="Selected disease estimated cases by sex"><text x="0" y="24" font-size="12">Male</text><rect x="70" y="11" width="${380*m/max}" height="16" rx="3" fill="#2a69b8"/><text x="${80+380*m/max}" y="24" font-size="12">${m.toLocaleString('en-IN')}</text><text x="0" y="62" font-size="12">Female</text><rect x="70" y="49" width="${380*f/max}" height="16" rx="3" fill="#c65a73"/><text x="${80+380*f/max}" y="62" font-size="12">${f.toLocaleString('en-IN')}</text></svg>`}
function detail(){const c=$('cohort').value,r=dataRow(),v=$('view').value;$('detail-title').textContent=v==='governance'?'Governance audit':v==='fhir'?'FHIR / DPDP controls':`${c} · NCRP analytics and HEOR view`;if(v==='governance'){$('detail').innerHTML='<div class="record"><b>DPDP legal basis</b><span class="tag warn">REVIEW</span></div><div class="record"><b>IEC / ICMR approval</b><span class="tag warn">REQUIRED</span></div><div class="record"><b>Residency / cross-border</b><span class="tag warn">NOT CONFIGURED</span></div><div class="record"><b>PBCR representativeness</b><span class="tag warn">DISCLOSE</span></div><div class="record"><b>HBCR referral adjustment</b><span class="tag warn">NOT IMPLEMENTED</span></div>'}else if(v==='fhir'){$('detail').innerHTML='<div class="code">FHIR R4 / DPDP control mapping · cancer site '+safe(r[0])+' · source vintage 2022 · consent scope, purpose limitation, residency, provenance, retention and access audit are required before exchange.</div>'}else{$('detail').innerHTML=sexChart(r)+`<div class="evidence"><b>${safe(map[c])}:</b> ${Number(r[9]||0).toLocaleString('en-IN')} estimated cases · both-sexes AAR ${r[11]??'—'} / 100,000 · male ${r[1]??'—'} · female ${r[5]??'—'}.</div><div class="evidence"><b>Real-time filter:</b> recalculated from the selected NCRP row whenever disease changes. Source is aggregate/modelled, not a live patient feed.</div><div class="evidence"><b>HEOR:</b> add survival, time-to-treatment, treatment completion, adverse events, hospitalizations, cost, QALYs and ICERs when patient-level data is approved.</div>`}}
function run(){const c=$('cohort').value,r=dataRow();$('steps').innerHTML=[['Policy gate','REVIEW · research only'],['Disease filter',`READY · ${map[c]} row selected`],['Schema','READY · count, sex, CR/AAR mapped'],['Cross-source','BLOCKED · no live PBCR/HBCR interoperability'],['Uncertainty','REVIEW · coverage, lag and referral bias'],['Human review','BLOCKED · IEC and disclosure review']].map(x=>`<div class="agent-step"><b>${x[0]}</b><span>${x[1]} <span class="tag ${x[1].startsWith('READY')?'ok':'warn'}">${x[1].split(' · ')[0]}</span></span></div>`).join('');$('answer').innerHTML=`<b>${safe(c)}:</b> ${Number(r[9]||0).toLocaleString('en-IN')} estimated NCRP cases in 2022. The result is recalculated from the workbook row, with aggregate-data caveats.`;metrics();detail()}
metrics();pathway();detail();$('cohort').onchange=()=>{metrics();pathway();detail()};$('view').onchange=detail;$('run').onclick=run;
const heor=window.IPCP_HEOR_DATA?.sheets||{},heorCancer={'Breast cancer':'Breast','Lung cancer':'Lung','Cervical cancer':'Cervical','Oral cavity cancer':'Oral cavity'};
function renderHEOR(){if($('view').value!=='heor')return;const c=heorCancer[$('cohort').value],out=heor['Outcomes_by_Cancer']||[],screen=heor['Screening_Coverage']||[],econ=heor['Economic_Burden']||[],bench=heor['HEOR_Benchmarks']||[];const find=(m)=>out.slice(1).find(r=>r[0]===c&&r[1]===m);const cases=find('New cases (2022)'),share=find('Share of all cancers (2022)'),surv=out.slice(1).find(r=>r[0]===c&&r[1].toLowerCase().includes('survival'));const scr=screen.slice(1).find(r=>String(r[0]).startsWith(c));const che=econ.slice(1).find(r=>String(r[0]).startsWith('Cancer'));const wtp=bench.slice(1).find(r=>String(r[0]).startsWith('Mean weighted'));$('detail-title').textContent=`${$('cohort').value} · HEOR dataset`;$('detail').innerHTML='<div class="record"><b>New cases (2022)</b><span>'+safe(cases?.[2]??'Not available')+' '+safe(cases?.[3]??'')+'</span></div><div class="record"><b>Share of all cancers</b><span>'+safe(share?.[2]??'Not available')+'</span></div><div class="record"><b>Survival evidence</b><span>'+safe(surv?.[2]??'Not systematically published')+'</span></div><div class="record"><b>Screening participation</b><span>'+safe(scr?.[2]??'Not available')+' '+safe(scr?.[3]??'')+'</span></div><div class="record"><b>Catastrophic health expenditure</b><span>'+safe(che?.[1]??'Not available')+' '+safe(che?.[2]??'')+'</span></div><div class="record"><b>Mean WTP per QALY</b><span>'+safe(wtp?.[1]??'Not available')+' '+safe(wtp?.[2]??'')+'</span></div><div class="notice">HEOR values are source-specific and cohort-specific. They are not patient-level outcomes and must not be combined without aligned population, time horizon, perspective, comparator and uncertainty assumptions.</div>'}
