const trialCond={'Breast cancer':'Breast Cancer','Lung cancer':'Lung Cancer','Cervical cancer':'Cervical Cancer','Oral cavity cancer':'Oral Cavity Cancer'};
function renderOncology(){if($('view').value!=='oncology')return;const c=$('cohort').value,cond=trialCond[c],type=heorCancer[c],out=heor['Outcomes_by_Cancer']||[],stage=out.slice(1).filter(r=>r[0]===type&&/stage|advanced|metast|locoregional/i.test(String(r[1]))),bio=type==='Cervical'?'HPV 16/18 attributable share: 0.80 (source-backed)':'Biomarker coverage not present in the HEOR workbook; ingest pathology/NGS source before reporting';const trialUrl='https://clinicaltrials.gov/search?cond='+encodeURIComponent(cond)+'&aggFilters=phase:EARLY_PHASE1%2CPHASE1%2CPHASE2%2CPHASE3%2CPHASE4%2CNA%2CSTATUS_RECRUITING%2CSTATUS_NOT_YET_RECRUITING%2CSTATUS_ACTIVE_NOT_RECRUITING';$('detail-title').textContent=`${c} · oncology intelligence`;$('detail').innerHTML='<div class="record"><b>Disease stage evidence</b><span>'+safe(stage.length?stage.map(r=>r[1]+': '+r[2]+' '+r[3]).join(' · '):'Not available in current workbook')+'</span></div><div class="record"><b>Biomarker application</b><span>'+safe(bio)+'</span></div><div class="record"><b>Market access</b><span><a href="https://www.cdsco.gov.in/opencms/opencms/en/Approval_new/Approved-New-Drugs/" target="_blank" rel="noopener">CDSCO approvals</a> · <a href="https://nppa.gov.in/en/proactivedisclosure" target="_blank" rel="noopener">NPPA prices</a> · status requires molecule/indication match</span></div><div class="record"><b>Regulatory dossier</b><span>CT/NDCT dossier checklist and indication claim: NOT INGESTED</span></div><div class="record"><b>Drug development / API molecules</b><span>API, INN, sponsor, phase, CMC and local manufacturing fields: NOT INGESTED</span></div><div class="record"><b>Current clinical trials</b><span><a href="${trialUrl}" target="_blank" rel="noopener">Open live ClinicalTrials.gov search</a> · status must be refreshed from registry API v2</span></div><div class="notice">ClinicalTrials.gov defines overall recruitment status and verification date in its study data model. The links above are live search entry points; this prototype does not claim a cached current trial count until a scheduled registry refresh is configured.</div><div class="evidence"><b>Required oncology intelligence schema:</b> CancerType, ICD-O/ICD-10, stage/TNM, biomarker, assay, drug/API/INN, sponsor, mechanism, indication, development phase, trial ID, recruitment status, last verified date, CDSCO status, NPPA/PM-JAY access, dossier evidence, source URL and confidence.</div>'}
$('view').addEventListener('change',renderOncology);$('cohort').addEventListener('change',renderOncology);renderOncology();
function fixTrialLink(){if($('view').value!=='oncology')return;const cond=trialCond[$('cohort').value],url='https://clinicaltrials.gov/search?cond='+encodeURIComponent(cond)+'&aggFilters=STATUS_RECRUITING%2CSTATUS_NOT_YET_RECRUITING%2CSTATUS_ACTIVE_NOT_RECRUITING';const link=[...$('detail').querySelectorAll('a')].find(a=>a.textContent.includes('Open live'));if(link)link.href=url}
$('view').addEventListener('change',fixTrialLink);$('cohort').addEventListener('change',fixTrialLink);fixTrialLink();
async function loadTrials(){if($('view').value!=='oncology')return;const cond=trialCond[$('cohort').value],host=[...$('detail').querySelectorAll('.record')].find(x=>x.textContent.includes('Clinical trials'));if(!host)return;try{const u='https://clinicaltrials.gov/api/v2/studies?query.cond='+encodeURIComponent(cond)+'&filter.overallStatus=RECRUITING%7CNOT_YET_RECRUITING%7CACTIVE_NOT_RECRUITING&pageSize=5&format=json';const data=await fetch(u).then(r=>r.ok?r.json():Promise.reject());const items=(data.studies||[]).map(s=>{const p=s.protocolSection||{},id=p.identificationModule?.nctId||'—',title=p.identificationModule?.briefTitle||'Untitled',status=p.statusModule?.overallStatus||'UNKNOWN',verified=p.statusModule?.statusVerifiedDate||'—';return `<div class="record"><b>${safe(id)}</b><span>${safe(status)} · verified ${safe(verified)}<br><small>${safe(title)}</small></span></div>`}).join('');host.querySelector('span').innerHTML=items||'No currently recruiting studies returned';refreshTrialChart();}catch(e){host.querySelector('span').innerHTML='Live registry refresh unavailable · use the ClinicalTrials.gov search link · no cached status asserted';refreshTrialChart()}}
