function trialStatusChart(){const counts={RECRUITING:0,NOT_YET_RECRUITING:0,ACTIVE_NOT_RECRUITING:0,OTHER:0};const items=[...$('detail').querySelectorAll('.record')].filter(x=>x.textContent.match(/verified/));items.forEach(x=>{const t=x.textContent;if(t.includes('RECRUITING')&&!t.includes('NOT_YET'))counts.RECRUITING++;else if(t.includes('NOT_YET_RECRUITING'))counts.NOT_YET_RECRUITING++;else if(t.includes('ACTIVE_NOT_RECRUITING'))counts.ACTIVE_NOT_RECRUITING++;else counts.OTHER++});const vals=Object.entries(counts).filter(x=>x[1]);return vals.length?'<div class="muted" style="margin:12px 0 6px">Live trial recruitment status</div><svg viewBox="0 0 620 120" role="img" aria-label="Live clinical trial status chart">'+vals.map((x,i)=>{const y=12+i*26;return `<text x="0" y="${y+14}" font-size="12">${x[0]}</text><rect x="210" y="${y}" width="${Math.max(8,36*x[1])}" height="18" rx="3" fill="${x[0]==='RECRUITING'?'#12715a':'#c68622'}"/><text x="${220+36*x[1]}" y="${y+14}" font-size="12">${x[1]}</text>`}).join('')+'</svg>':'<div class="notice">Waiting for live trial statuses…</div>'}
