function profileTests(){return oncologyProfiles[$('cohort').value].biomarkers.map(x=>({name:x[0],application:x[1],status:/required|source-backed|Molecular test|PCR/i.test(x[2])?'Mapped test':'Evidence pending',detail:x[2]}))}
