async function loadTrialsWorkspace(){if($('view').value!=='trials')return;const c=$('cohort').value;$('detail').querySelector('#trial-workspace').innerHTML='<div class="notice">Refreshing ClinicalTrials.gov API v2…</div>';try{const data=await fetch(trialQueryUrl(c)).then(r=>r.ok?r.json():Promise.reject());const studies=data.studies||[],counts={RECRUITING:0,NOT_YET_RECRUITING:0,ACTIVE_NOT_RECRUITING:0};const records=studies.map(s=>{const p=s.protocolSection||{},id=p.identificationModule?.nctId||'—',title=p.identificationModule?.briefTitle||'Untitled',status=p.statusModule?.overallStatus||'UNKNOWN',date=p.statusModule?.statusVerifiedDate||'—';if(counts[status]!=null)counts[status]++;return `<div class="record"><div><b>${safe(id)}</b><br><small>${safe(title)}</small></div><div><span class="tag ${status==='RECRUITING'?'ok':'warn'}">${safe(status)}</span><br><small>verified ${safe(date)}</small></div></div>`}).join('');const vals=Object.entries(counts).filter(x=>x[1]);const chart='<div class="muted" style="margin:12px 0 6px">Live recruitment status · '+new Date().toLocaleString()+'</div><svg viewBox="0 0 620 130" role="img" aria-label="Live trial status distribution">'+vals.map((x,i)=>{const y=12+i*32;return `<text x="0" y="${y+15}" font-size="12">${x[0]}</text><rect x="210" y="${y}" width="${Math.max(8,42*x[1])}" height="20" rx="3" fill="${x[0]==='RECRUITING'?'#12715a':'#c68622'}"/><text x="${220+42*x[1]}" y="${y+15}" font-size="12">${x[1]}</text>`}).join('')+'</svg>';$('detail').querySelector('#trial-workspace').innerHTML=chart+records+'<div class="muted">Source: ClinicalTrials.gov API v2 · '+studies.length+' studies returned for '+safe(c)+'</div>'}catch(e){$('detail').querySelector('#trial-workspace').innerHTML='<div class="notice">Live trial refresh unavailable. No cached count is asserted. Try again when network access is available.</div>'}}
function renderTrialsWorkspace(){if($('view').value!=='trials')return;const c=$('cohort').value;$('detail-title').textContent=`${c} · clinical trials`;$('detail').innerHTML='<div id="trial-workspace"></div><div class="notice">Recruitment status, trial ID and verification date are pulled at runtime. This is a research status view, not a referral or treatment recommendation.</div>';setTimeout(loadTrialsWorkspace,50)}
async function renderDrugDev(){if($('view').value!=='drugdev')return;const c=$('cohort').value,mols=publicMolecules[c]||[];$('detail-title').textContent=`${c} · API / drug development`;$('detail').innerHTML='<div class="evidence"><b>Public-source molecule intelligence:</b> PubChem compound metadata + openFDA label search are queried at runtime. Regulatory status is never inferred from a chemical record.</div><div id="molecule-workspace"><div class="notice">Refreshing PubChem and openFDA…</div></div>';const cards=await Promise.all(mols.map(async name=>{let pub=null,fda=false;try{const q=await fetch('https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/name/'+encodeURIComponent(name)+'/property/IUPACName,MolecularFormula,CanonicalSMILES/JSON').then(r=>r.ok?r.json():Promise.reject());pub=q.PropertyTable?.Properties?.[0]}catch(e){}try{const q=await fetch('https://api.fda.gov/drug/label.json?search=indications_and_usage:'+encodeURIComponent(name)+'&limit=1').then(r=>r.ok?r.json():Promise.reject());fda=!!q.results?.length}catch(e){}return {name,pub,fda}}));const ready=cards.filter(x=>x.pub).length;const chart=`<div class="chart-row">${pieChart(ready,cards.length,'molecules with live PubChem metadata')}<div class="evidence"><b>Development evidence coverage</b><br>${cards.filter(x=>x.fda).length}/${cards.length} names matched an openFDA label query.<br><small>Last refreshed ${new Date().toLocaleString()}</small></div></div>`;const html=cards.map(x=>`<div class="record"><div><b>${safe(x.name)}</b><br><small>${safe(x.pub?.MolecularFormula||'Formula unavailable')} · ${safe(x.pub?.IUPACName||'PubChem record unavailable')}</small></div><div><span class="tag ${x.fda?'ok':'warn'}">${x.fda?'openFDA label match':'label not found'}</span><br><small>${x.pub?'PubChem live':'PubChem unavailable'}</small></div></div>`).join('');$('detail').querySelector('#molecule-workspace').innerHTML=chart+html+'<div class="notice">API/INN, sponsor, phase, CMC, CDSCO and PM-JAY access require a controlled drug-development registry. These public lookups provide identity/evidence signals only.</div>'}
function routeSpecialized(){renderDiagnosis();renderBiomarkers();renderTrialsWorkspace();if($('view').value==='drugdev')renderDrugDev()}
$('view').addEventListener('change',routeSpecialized);$('cohort').addEventListener('change',routeSpecialized);routeSpecialized();
function tagHEORMarketAccess(){if($('view').value!=='heor'||$('detail').querySelector('#heor-market-access'))return;$('detail').insertAdjacentHTML('afterbegin','<div id="heor-market-access" class="record"><div><b>Market access ↔ HEOR</b><br><small>Indication, comparator, budget impact, WTP/QALY and access evidence are linked for this cancer cohort.</small></div><span class="tag ok">HEOR LINKED</span></div>')}
$('view').addEventListener('change',tagHEORMarketAccess);$('cohort').addEventListener('change',tagHEORMarketAccess);tagHEORMarketAccess();

function jevScore(item){const w=window.ICIP_JEV.weights;const score=item.quality*w.quality+item.applicability*w.applicability+item.recency*w.recency+item.consistency*w.consistency+item.provenance*w.provenance;const t=window.ICIP_JEV.thresholds;return {score,decision:score>=t.accept?'ACCEPT':score>=t.review?'REVIEW':'REJECT'}}
function jevBar(score){const pct=Math.round(score*100),color=score>=.78?'#12715a':score>=.55?'#c68622':'#b42318';return `<svg viewBox="0 0 420 28" role="img" aria-label="JEV evidence score"><rect x="0" y="4" width="360" height="18" rx="4" fill="#e5e7eb"/><rect x="0" y="4" width="${3.6*pct}" height="18" rx="4" fill="${color}"/><text x="372" y="18" font-size="12">${pct}/100</text></svg>`}
function jevSummary(){const items=window.ICIP_JEV.profiles[$('cohort').value]||[];const scores=items.map(jevScore),accepted=scores.filter(x=>x.decision==='ACCEPT').length;return `<div id="jev-summary" class="evidence"><b>JEV evidence gate:</b> ${accepted}/${items.length} predefined evidence options currently pass the accept threshold · model ${safe(window.ICIP_JEV.version)} · deterministic scoring, not a clinical recommendation.</div>`}
function renderJev(){if($('view').value!=='jev')return;const c=$('cohort').value,items=window.ICIP_JEV.profiles[c]||[];$('detail-title').textContent=`${c} · JEV evidence model`;$('detail').innerHTML='<div class="evidence"><b>JEV role in ICIP:</b> a fixed-choice evidence judge sits after source retrieval and before an agent can write a claim into an HEOR, market-access, trial, biomarker or governance artifact.</div>'+items.map((x,i)=>{const s=jevScore(x);return `<div class="record"><div><b>${safe(x.claim)}</b><br><small>${safe(x.source)}</small><br>${jevBar(s.score)}</div><div><span class="tag ${s.decision==='ACCEPT'?'ok':s.decision==='REVIEW'?'warn':'warn'}">${s.decision}</span><br><small>option: ${safe(x.option)}</small></div></div>`}).join('')+'<div class="notice"><b>Guardrail:</b> JEV scores source quality, applicability, recency, consistency and provenance. It must not be used to diagnose, prescribe, infer individual survival, or bypass IEC/DPDP/human review.</div><div class="code">'+safe(JSON.stringify({model:window.ICIP_JEV.modelName,weights:window.ICIP_JEV.weights,thresholds:window.ICIP_JEV.thresholds,adapter:'replace with approved JEV endpoint only after validation and data-processing review'},null,2))+'</div>'}
function addJevToDisease(){if($('view').value!=='oncology'||$('detail').querySelector('#jev-summary'))return;$('detail').insertAdjacentHTML('beforeend',jevSummary())}
$('view').addEventListener('change',renderJev);$('cohort').addEventListener('change',renderJev);$('view').addEventListener('change',addJevToDisease);$('cohort').addEventListener('change',addJevToDisease);renderJev();addJevToDisease();

function vaultTag(status){return `<span class="tag ${status==='VERIFIED'||status==='APPROVED'?'ok':'warn'}">${safe(status)}</span>`}
function renderVault(){if($('view').value!=='vault')return;const c=$('cohort').value,p=window.ICIP_VAULT.profiles[c],m=window.ICIP_VAULT.metrics;$('detail-title').textContent=`${c} · Vault longitudinal evidence`;$('detail').innerHTML='<div class="evidence"><b>Source-linked longitudinal evidence:</b> ICIP adapts the Vault pattern so AI proposes structured oncology details, every detail points to a source document and page, a person releases approved evidence, and unclear or mismatched fields stay on hold.</div><div class="chart-row">'+window.ICIP_VAULT.workflow.map((x,i)=>`<div class="evidence"><b>${i+1}. ${safe(x)}</b><br><small>${i===0?'bring documents and reports':i===1?'protect identifiers and check quality':i===2?'extract dates, findings and events':i===3?'compare proposal with original source':'release only approved records'}</small></div>`).join('')+'</div><div class="metrics"><div class="metric"><strong>'+m.syntheticPatients+'</strong><span>synthetic patients exercised</span></div><div class="metric"><strong>'+m.syntheticDocuments+'</strong><span>synthetic documents</span></div><div class="metric"><strong>'+m.reportTypes+'</strong><span>report types</span></div><div class="metric"><strong>'+m.identityMismatchesTested+'</strong><span>identity mismatches tested</span></div><div class="metric"><strong>'+m.annualCasesDiscussed+'</strong><span>annual cases discussed</span></div><div class="metric"><strong>'+m.plannedScale+'</strong><span>planned annual scale</span></div></div><h3 style="margin:18px 0 6px">Source-linked patient timeline · '+safe(p.recordId)+'</h3><div class="record"><div><b>'+safe(p.patient)+'</b><br><small>synthetic teaching record · '+p.documents+' source documents</small></div><span class="tag warn">NOT FOR CLINICAL USE</span></div>'+p.events.map(e=>`<div class="record"><div><b>${safe(e.date)} · ${safe(e.type)}</b><br><small>${safe(e.detail)}<br><a href="#" onclick="return false">Open source · ${safe(e.source)}</a></small></div>${vaultTag(e.status)}</div>`).join('')+'<h3 style="margin:18px 0 6px">Verification queue</h3>'+window.ICIP_VAULT.proposals.map(x=>`<div class="record"><div><b>${safe(x.field)}</b><br><small>${safe(x.value)}<br>Source: ${safe(x.source)}</small></div>${vaultTag(x.decision)}</div>`).join('')+'<div class="notice"><b>Release rule:</b> only APPROVED/VERIFIED fields enter the research-ready longitudinal record. REVIEW, HOLD, identity mismatch and unclear evidence remain visible for a human reviewer.</div><div class="evidence"><b>Measures to collect in an ICIP pilot:</b> '+m.measures.map(safe).join(' · ')+'<br><b>Proposed pilot:</b> '+safe(window.ICIP_VAULT.pilot.phase1)+' · '+safe(window.ICIP_VAULT.pilot.phase2)+' · '+safe(window.ICIP_VAULT.pilot.phase3)+' · '+safe(window.ICIP_VAULT.pilot.phase4)+'</div>'}
$('view').addEventListener('change',renderVault);$('cohort').addEventListener('change',renderVault);renderVault();

