function renderDiagnosis(){if($('view').value!=='diagnosis')return;const c=$('cohort').value,tests=profileTests(),ready=tests.filter(x=>x.status==='Mapped test').length,panels=ngsPanels[c],mols=stageMolecules[c];$('detail-title').textContent=`${c} · tests / diagnostics`;$('detail').innerHTML='<div class="evidence"><b>NGS-enabled diagnostic workflow:</b> pathology → stage/TNM → designated NGS panel → biomarker interpretation → treatment eligibility. No patient-level result is inferred.</div><div class="chart-row">'+pieChart(ready,tests.length,'biomarkers with mapped assay')+stageChart(oncologyProfiles[c])+'</div><div class="muted" style="margin:12px 0 6px">Designated next-generation sequencing panels</div>'+panels.map(x=>`<div class="record"><div><b>${safe(x[0])}</b><br><small>Biomarkers: ${safe(x[1])}</small></div><span class="tag ok">PANEL MAP</span></div>`).join('')+'<div class="muted" style="margin:12px 0 6px">Pharma / patented-molecule examples mapped to stage (jurisdictional patent status not asserted)</div>'+mols.map(x=>`<div class="record"><div><b>${safe(x[0])}</b><br><small>Branded/INN molecule examples</small></div><div>${safe(x[1])}</div></div>`).join('')+'<div class="notice">Molecule names are stage-linked evidence examples, not prescribing recommendations. Confirm Indian CDSCO indication, patent/exclusivity, comparator, and assay requirements before HEOR or market-access use.</div>'}
function renderTrialsWorkspace(){if($('view').value!=='trials')return;const c=$('cohort').value,landmarks=landmarkTrials[c]||[];$('detail-title').textContent=`${c} · clinical trials`;$('detail').innerHTML='<div id="trial-workspace"></div><div class="muted" style="margin:16px 0 6px">Landmark evidence · OS / PFS / ESMO/NCCN evidence pointers</div>'+landmarks.map(x=>`<div class="record"><div><b>${safe(x[0])}</b><br><small>${safe(x[1])}</small><br><small>${safe(x[2])} · ${safe(x[3])}</small></div><div><span class="tag ok">${safe(x[4])}</span><br><a href="${x[5]}" target="_blank" rel="noopener">evidence summary</a></div></div>`).join('')+'<div class="notice">OS/PFS values are trial-level evidence summaries and must be interpreted by line of therapy, biomarker, comparator, follow-up and endpoint definition. NCCN guideline pages may require an authorized account; the prototype stores a source-status flag rather than scraping restricted content.</div>';setTimeout(loadTrialsWorkspace,50)}
async function renderDrugDev(){if($('view').value!=='drugdev')return;const c=$('cohort').value,mols=publicMolecules[c]||[],players=pharmaPipelines[c]||[];$('detail-title').textContent=`${c} · API / drug development`;$('detail').innerHTML='<div class="evidence"><b>Public-source molecule intelligence:</b> PubChem + openFDA are queried at runtime; GCC and R&D rows are public research leads and require verification before market-access use.</div><div id="molecule-workspace"><div class="notice">Refreshing PubChem and openFDA…</div></div>';const cards=await Promise.all(mols.map(async name=>{let pub=null,fda=false;try{const q=await fetch('https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/name/'+encodeURIComponent(name)+'/property/IUPACName,MolecularFormula,CanonicalSMILES/JSON').then(r=>r.ok?r.json():Promise.reject());pub=q.PropertyTable?.Properties?.[0]}catch(e){}try{const q=await fetch('https://api.fda.gov/drug/label.json?search=indications_and_usage:'+encodeURIComponent(name)+'&limit=1').then(r=>r.ok?r.json():Promise.reject());fda=!!q.results?.length}catch(e){}return {name,pub,fda}}));const ready=cards.filter(x=>x.pub).length;const chart=`<div class="chart-row">${pieChart(ready,cards.length,'molecules with live PubChem metadata')}<div class="evidence"><b>Development evidence coverage</b><br>${cards.filter(x=>x.fda).length}/${cards.length} names matched an openFDA label query.<br><small>Last refreshed ${new Date().toLocaleString()}</small></div></div>`;const html=cards.map(x=>`<div class="record"><div><b>${safe(x.name)}</b><br><small>${safe(x.pub?.MolecularFormula||'Formula unavailable')} · ${safe(x.pub?.IUPACName||'PubChem record unavailable')}</small></div><div><span class="tag ${x.fda?'ok':'warn'}">${x.fda?'openFDA label match':'label not found'}</span><br><small>${x.pub?'PubChem live':'PubChem unavailable'}</small></div></div>`).join('');const gcc='<div class="muted" style="margin:12px 0 6px">Global pharma GCC / oncology R&D watchlist</div>'+players.map(x=>`<div class="record"><div><b>${safe(x[0])}</b><br><small>${safe(x[1])}</small></div><div>${safe(x[2])}</div></div>`).join('');$('detail').querySelector('#molecule-workspace').innerHTML=chart+html+gcc+'<div class="notice">API/INN, sponsor, phase, CMC, CDSCO and PM-JAY access require a controlled drug-development registry. These public lookups provide identity/evidence signals only.</div>'}
